---@alias gcp.unstable.displayvideo_v4.CampaignGoalCampaignGoalTypeEnum "CAMPAIGN_GOAL_TYPE_UNSPECIFIED"|"CAMPAIGN_GOAL_TYPE_APP_INSTALL"|"CAMPAIGN_GOAL_TYPE_BRAND_AWARENESS"|"CAMPAIGN_GOAL_TYPE_OFFLINE_ACTION"|"CAMPAIGN_GOAL_TYPE_ONLINE_ACTION"

